#include "v8_session.h"
#include <stdio.h>
#define CHECK(x) do{if(!(x)){fprintf(stderr,"V.8 session check failed at %d: %s\n",__LINE__,#x);return 1;}}while(0)
int main(void){struct v8_menu ca={.modes=V8_MODE_V21|V8_MODE_V22|V8_MODE_V32,.lapm=1},aa={.modes=V8_MODE_V21|V8_MODE_V22,.lapm=1};struct v8_session c,a;v8_session_init(&c,V8_CALL_DCE,&ca);v8_session_init(&a,V8_ANSWER_DCE,&aa);CHECK(a.state==V8_ANSAM);v8_session_ansam(&c);CHECK(c.state==V8_TE);v8_session_advance(&c,999);CHECK(c.state==V8_TE);v8_session_advance(&c,1);CHECK(c.state==V8_CM);v8_session_menu(&a,&ca);CHECK(a.state==V8_ANSAM);v8_session_menu(&a,&ca);CHECK(a.state==V8_JM&&a.selected==V8_MODE_V22);v8_session_menu(&c,&a.joint);v8_session_menu(&c,&a.joint);CHECK(c.state==V8_CJ&&c.selected==V8_MODE_V22);v8_session_cj(&c);v8_session_cj(&a);CHECK(a.state==V8_PAUSE&&c.state==V8_PAUSE);v8_session_advance(&a,75);v8_session_advance(&c,75);CHECK(a.state==V8_SELECTED&&c.state==V8_SELECTED);puts("V.8 session tests passed");return 0;}
